+function ensureCacheDirs(dirs: string[]): string[] {
+	for (const dir of dirs) {
+		if (!existsSync(dir) && existsSync(dirname(dir))) {
+			try {
+				mkdirSync(dir, { recursive: true });
+			} catch {
+				// Ungranted caches only fail the tools that need them.
+			}
+		}
+	}
+	return dirs;
